std::deque<int> data_dq = {10, 20, 30};

// Construct stack using deque (std::deque is the default container type)
std::stack<int> s1(data_dq);
// s1.top() == 30

std::vector<int> data_vec = {100, 200};

// Construct stack using vector (Requires explicit template specialization)
std::stack<int, std::vector<int>> s2(data_vec);
// s2.top() == 200

// Stack construction copies the elements.
// data_dq and s1 are independent.
